	parent := model.Task{
		ID:             parentID,
		ProjectID:      orch.projectID,
		Title:          "failed-parent-exhausted-new-commit",
		WorktreeBranch: info.Branch,
		Status:         model.StatusFailed,
		Context: map[string]any{
			"constraint_gate_exhausted":        true,
			"constraint_gate_failed_at_commit": oldSHA,
		},
	}
	db.Create(&parent)

	for i := 0; i < 2; i++ {
		sub := model.Task{
			ID:           uuid.New(),
			ProjectID:    orch.projectID,
			ParentTaskID: &parentID,
			Title:        "done-sub",
			Status:       model.StatusDone,
		}
		db.Create(&sub)
	}

	n, err := orch.reconcileFailedParents()
	if err != nil {
		t.Fatalf("reconcileFailedParents() error: %v", err)
	}
	if n != 1 {
		t.Errorf("expected 1 parent recovered after new commit, got %d", n)
	}

	var updated model.Task
	db.First(&updated, "id = ?", parentID)
	if updated.Status == model.StatusFailed {
		t.Errorf("parent should have been recovered, still %s", updated.Status)
	}

	// Assert context is cleared
	if val, ok := updated.Context["constraint_gate_exhausted"]; ok && val != nil {
		t.Errorf("constraint_gate_exhausted should have been cleared, got %v", val)
	}
	if val, ok := updated.Context["constraint_gate_failed_at_commit"]; ok && val != nil {
		t.Errorf("constraint_gate_failed_at_commit should have been cleared, got %v", val)
	}
}

